/* Generated by port_site.py from the approved mockup. Behaviour for the stay section; timers, listeners and observers go through ctx. */
export function init(ctx) {
  var reduce = ctx.reduce,
    root = document.documentElement;

  /* section 8: before check-in the checklist ticks itself, during the stay a problem walks the relay, at check-out the inspection ticks and the deposit goes back. Loops while in view. */
  (function () {
    var wrap = document.getElementById("ops8"),
      ck = document.getElementById("ck8"),
      rl = document.getElementById("rl8"),
      list = document.getElementById("ck8list"),
      tag = document.getElementById("ck8tag"),
      title = document.getElementById("ck8title"),
      count = document.getElementById("ck8count"),
      foot = document.getElementById("ck8foot"),
      ft = document.getElementById("ck8ft"),
      gm = document.getElementById("gm8"),
      rows = [].slice.call(document.querySelectorAll("#ld8 li")),
      fx = document.getElementById("fx8"),
      timers = [],
      seen = false,
      running = false;
    if (reduce) return;
    var MODES = {
      ready: {
        tag: "Before check-in",
        title: "Ready to welcome",
        items: [
          "Pool cleaned",
          "AC and hot water working",
          "Fresh linen in every room",
          "Welcome kit placed",
        ],
        foot: "Ready. Meera arrives at 1 PM.",
      },
      out: {
        tag: "At check-out",
        title: "Check-out inspection",
        items: [
          "Rooms and bathrooms",
          "Kitchen and gas",
          "Pool and garden",
          "Nothing missing or broken",
        ],
        foot: "All fine. ₹5,000 deposit returned.",
      },
    };
    function at(ms, fn) {
      timers.push(ctx.setTimeout(fn, ms));
    }
    function clear() {
      timers.forEach(clearTimeout);
      timers = [];
    }
    function focus(el) {
      ck.classList.toggle("on", el === ck);
      rl.classList.toggle("on", el === rl);
    }
    function checklist(mode, start) {
      var m = MODES[mode],
        lis = [].slice.call(list.children);
      at(start, function () {
        focus(ck);
        tag.textContent = m.tag;
        title.textContent = m.title;
        foot.classList.remove("in");
        ft.textContent = m.foot;
        lis.forEach(function (li, i) {
          li.classList.remove("ok");
          li.querySelector(".tx8").textContent = m.items[i];
        });
        count.textContent = "0 of " + lis.length;
      });
      lis.forEach(function (li, i) {
        at(start + 500 + i * 520, function () {
          li.classList.add("ok");
          count.textContent = i + 1 + " of " + lis.length;
        });
      });
      at(start + 500 + lis.length * 520 + 200, function () {
        foot.classList.add("in");
      });
      return start + 500 + lis.length * 520 + 1600;
    }
    function relay(start) {
      at(start, function () {
        focus(rl);
        gm.classList.remove("in");
        fx.classList.remove("in");
        rows.forEach(function (r) {
          r.classList.remove("pass", "ring");
          var st = r.querySelector(".st8");
          st.className = "st8";
          st.textContent = "";
        });
      });
      at(start + 400, function () {
        gm.classList.add("in");
      });
      at(start + 1100, function () {
        rows[0].classList.add("ring");
        var st = rows[0].querySelector(".st8");
        st.className = "st8 wait in";
        st.textContent = "Alerted";
      });
      at(start + 2600, function () {
        rows[0].classList.remove("ring");
        rows[0].classList.add("pass");
        var st = rows[0].querySelector(".st8");
        st.className = "st8 no in";
        st.textContent = "No reply, 5 min";
      });
      at(start + 3000, function () {
        rows[1].classList.add("ring");
        var st = rows[1].querySelector(".st8");
        st.className = "st8 wait in";
        st.textContent = "Alerted";
      });
      at(start + 4100, function () {
        rows[1].classList.remove("ring");
        var st = rows[1].querySelector(".st8");
        st.className = "st8 yes in";
        st.textContent = "On it";
      });
      at(start + 5000, function () {
        fx.classList.add("in");
      });
      return start + 6800;
    }
    function cycle() {
      clear();
      running = true;
      var t = checklist("ready", 0);
      t = relay(t);
      t = checklist("out", t);
      at(t + 600, function () {
        if (seen) cycle();
        else running = false;
      });
    }
    wrap.classList.add("js");
    focus(ck);
    if ("IntersectionObserver" in window)
      ctx
        .io(
          function (es) {
            seen = es[0].isIntersecting;
            if (seen && !running) cycle();
          },
          { threshold: 0.35 },
        )
        .observe(wrap);
    else {
      seen = true;
      cycle();
    }
  })();
}
